package com.mfg.qms.service;
import com.mfg.common.api.ErrorCode;import com.mfg.common.exception.BizException;import com.mfg.common.integration.BusinessEventService;import com.mfg.security.config.CurrentUser;import com.mfg.wms.dto.InventoryActionCommand;import com.mfg.wms.service.InventoryTransactionService;import lombok.RequiredArgsConstructor;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.util.*;
@Service @RequiredArgsConstructor public class QmsLifecycleService{private final JdbcTemplate db;private final InventoryTransactionService inventory;private final BusinessEventService events;
 @Transactional public Map<String,Object>judge(long id,BigDecimal good,BigDecimal bad,String result){Map<String,Object>i=one("SELECT * FROM src_qms.qms_inspection WHERE id=? FOR UPDATE",id);if(!"PENDING".equals(i.get("inspect_result")))throw state("检验单已经判定");BigDecimal total=d(i,"inspected_qty");if(good.add(bad).compareTo(total)!=0)throw state("合格数与不合格数之和必须等于送检数");if(!Set.of("PASSED","FAILED","CONCESSION","REWORK","RETURN","SCRAPPED").contains(result))throw state("非法检验结论");db.update("UPDATE src_qms.qms_inspection SET qualified_qty=?,defect_qty=?,defect_rate=?,inspect_result=? WHERE id=?",good,bad,total.signum()==0?BigDecimal.ZERO:bad.divide(total,4,RoundingMode.HALF_UP),result,id);var receipts=i.get("source_no")==null?List.<Map<String,Object>>of():db.queryForList("SELECT * FROM src_wms.wms_receipt WHERE receipt_no=? FOR UPDATE",i.get("source_no"));if(!receipts.isEmpty()){Map<String,Object>r=receipts.get(0);String base="QMS:"+i.get("inspection_no");InventoryActionCommand in=new InventoryActionCommand(base+":RECEIPT",String.valueOf(r.get("material_code")),String.valueOf(r.get("warehouse_code")),null,(String)r.get("batch_no"),total,"QMS",String.valueOf(i.get("inspection_no")),"质量判定入账");inventory.action("RECEIPT",in);if(Set.of("FAILED","REWORK").contains(result))inventory.action("QUARANTINE",copy(in,base+":QUARANTINE",total));else if("RETURN".equals(result))inventory.action("SUPPLIER_RETURN",copy(in,base+":RETURN",total));else if("SCRAPPED".equals(result))inventory.action("SCRAP",copy(in,base+":SCRAP",total));db.update("UPDATE src_wms.wms_receipt SET status=? WHERE id=?",Set.of("PASSED","CONCESSION").contains(result)?"AVAILABLE":result,r.get("id"));}if(bad.signum()>0)createNcr(i,bad,total);events.publish("QMS.INSPECTION.JUDGED","qms","wms","INSPECTION",id,Map.of("inspectionNo",i.get("inspection_no"),"result",result));return one("SELECT * FROM src_qms.qms_inspection WHERE id=?",id);}
 @Transactional public Map<String,Object>dispose(long id,String disposition,String reason){Map<String,Object>n=one("SELECT * FROM src_qms.qms_ncr WHERE id=? FOR UPDATE",id);if(!Set.of("OPEN","REVIEWING").contains(String.valueOf(n.get("status"))))throw state("当前NCR不能处置");if(disposition==null||!Set.of("REWORK","SCRAPPED","CONCESSION","RETURNED").contains(disposition))throw state("请选择有效的不合格处置结论");db.update("UPDATE src_qms.qms_ncr SET status=?,disposition=?,remark=COALESCE(NULLIF(?,''),remark) WHERE id=?",disposition,disposition,reason,id);events.publish("QMS.NCR.DISPOSED","qms",disposition.equals("RETURNED")?"srm":"wms","NCR",id,Map.of("ncrNo",n.get("ncr_no"),"disposition",disposition));return one("SELECT * FROM src_qms.qms_ncr WHERE id=?",id);}
 @Transactional public Map<String,Object>verify(String kind,long id){String table,expected;if("capas".equals(kind)){table="src_qms.qms_capa";expected="IMPLEMENTING";}else if("8d".equals(kind)){table="src_qms.qms_eight_d";expected="SUBMITTED";}else throw state("不支持的质量验证类型");Map<String,Object>row=one("SELECT * FROM "+table+" WHERE id=? FOR UPDATE",id);if(!expected.equals(String.valueOf(row.get("status"))))throw state("当前单据状态不允许验证");db.update("UPDATE "+table+" SET status='VERIFYING',verified_by=?,verified_at=NOW(3) WHERE id=?",CurrentUser.usernameOrSystem(),id);return one("SELECT * FROM "+table+" WHERE id=?",id);}
 @Transactional public Map<String,Object>close(String kind,long id){String table;if("capas".equals(kind))table="src_qms.qms_capa";else if("8d".equals(kind))table="src_qms.qms_eight_d";else throw state("不支持的质量关闭类型");Map<String,Object>row=one("SELECT * FROM "+table+" WHERE id=? FOR UPDATE",id);if(!"VERIFYING".equals(String.valueOf(row.get("status"))))throw state("只有验证中的质量单据可以关闭");Object result=row.get("effectiveness_result");if("FAILED".equals(result))throw state("有效性验证未通过，不能关闭");db.update("UPDATE "+table+" SET status='CLOSED',closed_at=NOW(3),closed_by=? WHERE id=?",CurrentUser.usernameOrSystem(),id);return one("SELECT * FROM "+table+" WHERE id=?",id);}
 private void createNcr(Map<String,Object>i,BigDecimal bad,BigDecimal total){String no="NCR"+System.currentTimeMillis();db.update("INSERT INTO src_qms.qms_ncr(ncr_no,inspection_no,source_no,material_code,supplier_code,defect_qty,severity,status) VALUES(?,?,?,?,?,?,'MAJOR','OPEN')",no,i.get("inspection_no"),i.get("source_no"),i.get("material_code"),i.get("supplier_code"),bad);String issue="SQ"+System.currentTimeMillis();BigDecimal ppm=total.signum()==0?BigDecimal.ZERO:bad.multiply(BigDecimal.valueOf(1000000)).divide(total,2,RoundingMode.HALF_UP);db.update("INSERT INTO src_srm.srm_supplier_quality(issue_no,supplier_code,source_no,defect_qty,ppm,problem_desc) VALUES(?,?,?,?,?,?)",issue,i.get("supplier_code"),i.get("source_no"),bad,ppm,"IQC不合格，NCR="+no);}private InventoryActionCommand copy(InventoryActionCommand c,String key,BigDecimal q){return new InventoryActionCommand(key,c.materialCode(),c.warehouseCode(),c.locationCode(),c.batchNo(),q,"QMS",c.sourceNo(),c.reason());}private Map<String,Object>one(String q,Object...a){var x=db.queryForList(q,a);if(x.isEmpty())throw BizException.notFound("业务记录","未知");return x.get(0);}private BigDecimal d(Map<String,Object>r,String k){Object v=r.get(k);return v instanceof BigDecimal b?b:new BigDecimal(String.valueOf(v));}private BizException state(String m){return BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,m);}}
